parameters.jsCode:
const body = $input.item.json.body || $input.item.json;

const patientName = body.patient_name || body.name || '';
const patientEmail = body.patient_email || body.email || '';
const patientPhone = body.patient_phone || body.phone || '';
const doctorName = body.doctor_name || body.doctor || 'Dr. Smith';
const appointmentDate = body.appointment_date || body.date || '';
const appointmentTime = body.appointment_time || body.time || '';
const appointmentType = body.appointment_type || body.type || 'General Consultation';
const notes = body.notes || body.reason || '';

if (!patientEmail || !appointmentDate || !appointmentTime) {
  return [{ json: { error: 'Missing required fields: email, date, or time' } }];
}

const bookingId = 'APT-' + Date.now();
const dateTimeStr = appointmentDate + 'T' + appointmentTime + ':00';
const startDateTime = new Date(dateTimeStr).toISOString();
const endDateTime = new Date(new Date(dateTimeStr).getTime() + 30 * 60000).toISOString();

return [{ json: {
  patientName,
  patientEmail,
  patientPhone,
  doctorName,
  appointmentDate,
  appointmentTime,
  appointmentType,
  notes,
  bookingId,
  startDateTime,
  endDateTime,
  createdAt: new Date().toISOString()
}}];

